"""Causal EKF demonstration, with measured-voltage and synthetic-state validation."""

from pathlib import Path as _CasePath
import sys as _case_sys
_CASE_DIR = _CasePath(__file__).resolve().parents[1]
_case_sys.path.insert(0, str(_CASE_DIR))
_case_sys.path.insert(0, str(_CASE_DIR / "_impl"))
from study_common import *

def run(ctx):
    out=ctx.output('state_estimation'); arrays={}; real=[]
    for p in ctx.protocols('test'):
        g=ctx.grid(p,5.); prior=ctx.open_loop(g,ctx.initial(p)); estimate=filter_profile(ctx,g,ctx.initial(p)); burn=g['t']>=300; observed_burn=estimate['observation_time_s']>=300; e=estimate['observation_prior_voltage'][observed_burn]-estimate['observation_voltage'][observed_burn]
        r={'protocol':p['file'],'reporting_grid_seconds':5,'observation_timestamps':'Original released measurement timestamps; no interpolated future voltage assimilated.','burn_in_seconds':300,'openloop_voltage_error':error_metrics(estimate['observation_openloop_voltage'][observed_burn]-estimate['observation_voltage'][observed_burn]),'causal_one_step_prior_voltage_error':error_metrics(e),'posterior_voltage_error':error_metrics(estimate['observation_posterior_voltage'][observed_burn]-estimate['observation_voltage'][observed_burn]),'mean_normalized_innovation_squared':float(np.mean(estimate['innovation'][observed_burn]**2/estimate['innovation_variance'][observed_burn])),'posterior_soc_min':float(estimate['state'][:,0].min()),'posterior_soc_max':float(estimate['state'][:,0].max()),'posterior_soc_violation_fraction':float(np.mean((estimate['state'][:,0]<0)|(estimate['state'][:,0]>1))),'median_posterior_soc_std':float(np.median(np.sqrt(estimate['covariance'][burn,0,0]))),'measured_soc_rmse':None,'voltage_noise_and_discrepancy_std_assumed_V':.02,'process_std_SOC_per_sqrt_second':1e-5,'process_std_polarization_V_per_sqrt_second':1e-4,'covariance_interpretation':'Conditional EKF covariance; parameter uncertainty/model bias omitted, not calibrated SOC confidence.'}; real.append(r)
        stem=p['file'][:-4]; arrays.update({stem+'__time_s':g['t'],stem+'__current_A':g['i'],stem+'__exact_voltage_V':g['v'],stem+'__openloop_prediction':prior,**{stem+'__ekf_'+k:v for k,v in estimate.items()}})
        fig,ax=plt.subplots(3,1,figsize=(10,8),sharex=True); ax[0].plot(estimate['observation_time_s']/3600,estimate['observation_openloop_voltage']-estimate['observation_voltage'],label='open loop'); ax[0].plot(estimate['observation_time_s']/3600,estimate['observation_prior_voltage']-estimate['observation_voltage'],label='EKF prior'); ax[0].set_ylabel('Voltage error (V)'); ax[0].legend(); ax[1].plot(g['t']/3600,estimate['state'][:,0],label='EKF inferred SOC'); ax[1].plot(g['t']/3600,prior[:,0],label='open-loop inferred SOC'); ax[1].set_ylabel('SOC (unobserved)'); ax[1].legend(); ax[2].plot(estimate['observation_time_s']/3600,estimate['innovation']); ax[2].set_ylabel('Innovation (V)'); ax[2].set_xlabel('Time (h)'); fig.tight_layout(); fig.savefig(out/(stem+'_filter.png'),dpi=140); plt.close(fig)
    synthetic=[]
    for z0 in [.2,.5,.8]:
        for bias in [-.05,.05]:
            for seed in [11,22,33]:
                rng=np.random.default_rng(seed); t=np.arange(0,1800+5,5.); current=np.repeat(rng.uniform(-80,80,31),12)[:len(t)]; avg=np.r_[current[0],.5*(current[:-1]+current[1:])]; g={'t':t,'i':current,'avg':avg,'dt':np.r_[0,np.diff(t)]}; truth=ctx.open_loop(g,initial_state(ctx.saved.config,z0)); g['v']=truth[:,-1]+rng.normal(0,.005,len(t)); initial=initial_state(ctx.saved.config,z0+bias,.02); openloop=ctx.open_loop(g,initial); estimate=filter_profile(ctx,g,initial,voltage_sigma=.005); use=t>=300
                synthetic.append({'initial_soc':z0,'initial_soc_bias':bias,'seed':seed,'openloop_soc_rmse':rmse(openloop[use,0]-truth[use,0]),'ekf_soc_rmse':rmse(estimate['state'][use,0]-truth[use,0]),'ekf_polarization_rmse_V':rmse(estimate['state'][use,1]-truth[use,1]),'conditional_2sigma_soc_coverage':float(np.mean(abs(estimate['state'][use,0]-truth[use,0])<=2*np.sqrt(estimate['covariance'][use,0,0]))),'truth_source':'Synthetic identical learned model; verifies algorithm behavior only.'})
                if z0==.5 and bias==.05 and seed==11:
                    arrays.update(synthetic_time_s=t,synthetic_truth=truth,synthetic_noisy_voltage_V=g['v'],synthetic_ekf_state=estimate['state'],synthetic_openloop=openloop)
                    fig,ax=plt.subplots(figsize=(9,4)); ax.plot(t,truth[:,0],label='synthetic truth'); ax.plot(t,openloop[:,0],label='open loop, biased init'); ax.plot(t,estimate['state'][:,0],label='EKF'); ax.set_xlabel('Time (s)'); ax.set_ylabel('SOC'); ax.legend(); fig.tight_layout(); fig.savefig(out/'synthetic_soc_recovery.png',dpi=140); plt.close(fig)
    metrics={'real_experiments':real,'synthetic_experiments':synthetic,'filter':'Extended Kalman filter, autodiff F/H, Joseph covariance update; no state clipping or inequalities.','synthetic_median_openloop_soc_rmse':float(np.median([r['openloop_soc_rmse'] for r in synthetic])),'synthetic_median_ekf_soc_rmse':float(np.median([r['ekf_soc_rmse'] for r in synthetic])),'limitation':'Real SOC accuracy cannot be established without independent labels. Posterior voltage fit uses the same assimilated measurement; causal prior and subsequent forecasts are the application metrics.'}
    lines=['# State-estimation application','','| Measured experiment | Open-loop voltage RMSE (mV) | Causal EKF prior RMSE (mV) | Posterior fit RMSE (mV) | SOC violations |','|---|---:|---:|---:|---:|']
    for r in real: lines.append(f"| {r['protocol']} | {r['openloop_voltage_error']['rmse_V']*1000:.3f} | {r['causal_one_step_prior_voltage_error']['rmse_V']*1000:.3f} | {r['posterior_voltage_error']['rmse_V']*1000:.3f} | {r['posterior_soc_violation_fraction']:.5f} |")
    lines+=['',f"Synthetic identical-model check: median SOC RMSE changes from {metrics['synthetic_median_openloop_soc_rmse']:.5f} to {metrics['synthetic_median_ekf_soc_rmse']:.5f}. This is not measured-cell SOC validation.",'',metrics['limitation'],'','The EKF integrates on the union of original measurement timestamps and reporting times, preserving the current integral. Only original voltage observations are assimilated, at their original times. The 5 s grid is for forecast/reporting states, not fabricated sensor observations. Current is a supplied known profile. Filter settings are fixed assumptions, not test-tuned optimal values. Bounds are monitored without adding the inequality formulation postponed by the user.']
    return ctx.report('state_estimation',metrics,lines,arrays)
if __name__=='__main__':
    args=parser(__doc__).parse_args(); print(run(Context(args.model_dir,args.study)))
